    val sections: List<Pair<String, String>> = listOf(
        "UA" to "Україна",
        "WORLD" to "Музика світу",
    )

    fun bySection(code: String): List<MusicTvChannel> = when (code) {
        "UA" -> all.filter { it.country == "UA" }
        "WORLD" -> all.filter { it.country != "UA" }
        else -> emptyList()
    }

    fun byCountry(code: String): List<MusicTvChannel> = bySection(code)
